var root = new ArcSunburstNode(
    "All teams",
    new ArcSunburstNode("Platform",
        new ArcSunburstNode("Compute",
            new ArcSunburstNode("api", 18910),
            new ArcSunburstNode("batch", 8160)),
        new ArcSunburstNode("Storage", 8670)),
    new ArcSunburstNode("Data",
        new ArcSunburstNode("Warehouse", 31020),
        new ArcSunburstNode("Pipelines", 9400)));

var chart = new ArcSunburstChart
{
    Root = root,
    CenterLabel = "Cloud spend",
    Depth = 3,
    ValueFormat = value => "$" + (value / 1000).ToString("0.#") + "K"
};

chart.NodeSelected += (_, selection) =>
    Console.WriteLine(string.Join(" / ", selection.Path.Select(node => node.Label)));
